1	import { createServer, type IncomingMessage, type ServerResponse } from "node:http";
2	import { existsSync, readFileSync, statSync } from "node:fs";
3	import { extname, resolve, sep } from "node:path";
4	import { timingSafeEqual } from "node:crypto";
5	import { verifyProof, type SemaphoreProof } from "@semaphore-protocol/proof";
6	import { openCatalog, STATUSES, type AuditQuery, type GroupOperation, type NewPollInput } from "./store.ts";
7	import { isCommitment, isProofPayload, terminateProverWorkers, textToField } from "./voting.ts";
8	import { parseInstant } from "./time.ts";
9	import type { AuditEvent, PollStatus } from "./types.ts";
10	
11	const MAX_BODY_BYTES = 1_000_000;
12	
13	export interface AppOptions {
14	  /** When unset (or empty) every administrative request is refused with 401. */
15	  adminToken?: string;
16	}
17	
18	function readBody(request: IncomingMessage): Promise<string> {
19	  return new Promise((resolvePromise, rejectPromise) => {
20	    const chunks: Buffer[] = [];
21	    let size = 0;
22	    request.on("data", (chunk: Buffer) => {
23	      size += chunk.length;
24	      if (size > MAX_BODY_BYTES) { rejectPromise(new Error("body_too_large")); request.destroy(); return; }
25	      chunks.push(chunk);
26	    });
27	    request.on("end", () => resolvePromise(Buffer.concat(chunks).toString("utf8")));
28	    request.on("error", rejectPromise);
29	  });
30	}
31	
32	function isNonEmptyString(value: unknown, maxLength = 2000): value is string {
33	  return typeof value === "string" && value.trim().length > 0 && value.length <= maxLength;
34	}
35	
36	export function createApp(databasePath: string, publicPath = resolve("dist/public"), options: AppOptions = {}) {
37	  const catalog = openCatalog(databasePath);
38	  const adminToken = options.adminToken && options.adminToken.length > 0 ? options.adminToken : undefined;
39	  let proverUsed = false;
40	  const mime: Record<string, string> = { ".html": "text/html; charset=utf-8", ".js": "text/javascript; charset=utf-8", ".css": "text/css; charset=utf-8", ".svg": "image/svg+xml", ".json": "application/json; charset=utf-8" };
41	  const server = createServer((request, response) => {
42	    handle(request, response).catch(() => {
43	      if (!response.headersSent) response.writeHead(500, { "Content-Type": "application/json; charset=utf-8", "Cache-Control": "no-store" });
44	      response.end(JSON.stringify({ error: "internal_error" }));
45	    });
46	  });
47	  server.on("close", () => {
48	    catalog.close();
49	    // Release the snarkjs worker pool so the process can exit.
50	    if (proverUsed) void terminateProverWorkers();
51	  });
52	  return server;
53	
54	  /**
55	   * Authorization gate for management endpoints. A missing, wrong or
56	   * unconfigured token is refused with 401 admin_unauthorized. The check
57	   * runs before the body is read and never mutates data or writes audit.
58	   */
59	  function isAuthorized(request: IncomingMessage): boolean {
60	    if (!adminToken) return false;
61	    const provided = request.headers["x-admin-token"];
62	    if (typeof provided !== "string") return false;
63	    const expected = Buffer.from(adminToken);
64	    const actual = Buffer.from(provided);
65	    return expected.length === actual.length && timingSafeEqual(expected, actual);
66	  }
67	
68	  async function handle(request: IncomingMessage, response: ServerResponse) {
69	    function json(status: number, payload: unknown, headers: Record<string, string> = {}) {
70	      response.writeHead(status, { "Content-Type": "application/json; charset=utf-8", "Cache-Control": "no-store", ...headers });
71	      response.end(JSON.stringify(payload));
72	    }
73	    function requireAdmin(): boolean {
74	      if (isAuthorized(request)) return true;
75	      json(401, { error: "admin_unauthorized" });
76	      return false;
77	    }
78	    const url = new URL(request.url ?? "/", "http://localhost");
79	    const segments = url.pathname.split("/").filter(Boolean);
80	    if (segments[0] === "api") {
81	      const method = request.method ?? "GET";
82	      if (url.pathname === "/api/health") {
83	        if (method !== "GET") return json(405, { error: "method_not_allowed" }, { Allow: "GET" });
84	        return json(200, { service: "veilvote", status: "ok" });
85	      }
86	      if (segments[1] === "admin" && segments[2] === "audit" && segments.length === 3) {
87	        if (method !== "GET") return json(405, { error: "method_not_allowed" }, { Allow: "GET" });
88	        if (!requireAdmin()) return;
89	        const query = parseAuditQuery(url.searchParams);
90	        if (!query.ok) return json(400, { error: query.error });
91	        return json(200, catalog.auditQuery(query.query));
92	      }
93	      if (segments[1] === "polls" && segments.length <= 4) {
94	        if (segments.length === 2) {
95	          // Public catalog list; creating a poll is admin-only and starts in draft.
96	          if (method === "GET") return json(200, { polls: catalog.list(Date.now(), isAuthorized(request)) });
97	          if (method !== "POST") return json(405, { error: "method_not_allowed" }, { Allow: "GET, POST" });
98	          if (!requireAdmin()) return;
99	          let body: unknown;
100	          try { body = JSON.parse(await readBody(request)); }
101	          catch {
102	            catalog.auditFailure("poll_create", "unknown", { reason: "invalid_json" });
103	            return json(400, { error: "invalid_json" });
104	          }
105	          const parsed = parseNewPoll(body);
106	          if (!parsed.ok) {
107	            catalog.auditFailure("poll_create", parsed.pollId, { reason: parsed.reason });
108	            return json(400, { error: parsed.reason });
109	          }
110	          const outcome = catalog.createPoll(parsed.input);
111	          if (!outcome.ok) {
112	            catalog.auditFailure("poll_create", parsed.input.id, { reason: "poll_exists" });
113	            return json(409, { error: "poll_exists" });
114	          }
115	          return json(201, { poll: outcome.poll });
116	        }
117	        let id: string;
118	        try { id = decodeURIComponent(segments[2]); }
119	        catch { return json(400, { error: "invalid_poll_id" }); }
120	        if (segments.length === 3) {
121	          if (method !== "GET") return json(405, { error: "method_not_allowed" }, { Allow: "GET" });
122	          const poll = catalog.get(id);
123	          // Drafts are invisible to ordinary detail requests; an authorized
124	          // manager can still read them to prepare the opening.
125	          if (!poll || (poll.status === "draft" && !isAuthorized(request))) return json(404, { error: "poll_not_found" });
126	          return json(200, { poll });
127	        }
128	        if (segments[3] === "results") {
129	          if (method !== "GET") return json(405, { error: "method_not_allowed" }, { Allow: "GET" });
130	          const result = catalog.results(id);
131	          return result ? json(200, { result }) : json(404, { error: "poll_not_found" });
132	        }
133	        if (segments[3] === "status") {
134	          if (method !== "POST") return json(405, { error: "method_not_allowed" }, { Allow: "POST" });
135	          if (!requireAdmin()) return;
136	          let body: unknown;
137	          try { body = JSON.parse(await readBody(request)); }
138	          catch {
139	            catalog.auditFailure("status_change_rejected", id, { reason: "invalid_json" });
140	            return json(400, { error: "invalid_json" });
141	          }
142	          if (typeof body !== "object" || body === null) {
143	            catalog.auditFailure("status_change_rejected", id, { reason: "invalid_status" });
144	            return json(400, { error: "invalid_status" });
145	          }
146	          const { status, expectedStatus } = body as { status?: unknown; expectedStatus?: unknown };
147	          if (!isStatus(status) || !isStatus(expectedStatus)) {
148	            catalog.auditFailure("status_change_rejected", id, { reason: "invalid_status", requested: String(status), expected: String(expectedStatus) });
149	            return json(400, { error: "invalid_status" });
150	          }
151	          const outcome = catalog.transitionStatus(id, status, expectedStatus);
152	          if (!outcome.ok) {
153	            if (outcome.reason === "poll_missing") return json(404, { error: "poll_not_found" });
154	            if (outcome.reason === "invalid_status") return json(400, { error: "invalid_status" });
155	            return json(409, { error: outcome.reason });
156	          }
157	          const poll = catalog.get(id);
158	          return json(200, { status: outcome.status, poll });
159	        }
160	        if (segments[3] === "group") {
161	          if (method !== "POST") return json(405, { error: "method_not_allowed" }, { Allow: "POST" });
162	          if (!requireAdmin()) return;
163	          let body: unknown;
164	          try { body = JSON.parse(await readBody(request)); }
165	          catch {
166	            catalog.auditFailure("group_change_rejected", id, { reason: "invalid_json" });
167	            return json(400, { error: "invalid_json" });
168	          }
169	          if (typeof body !== "object" || body === null) {
170	            catalog.auditFailure("group_change_rejected", id, { reason: "invalid_group_operation" });
171	            return json(400, { error: "invalid_group_operation" });
172	          }
173	          const { operation, expectedVersion, commitment, oldCommitment, newCommitment } = body as Record<string, unknown>;
174	          if (!Number.isInteger(expectedVersion) || (expectedVersion as number) < 1) {
175	            catalog.auditFailure("group_change_rejected", id, { operation: String(operation), reason: "invalid_group_operation" });
176	            return json(400, { error: "invalid_group_operation" });
177	          }
178	          let groupOperation: GroupOperation;
179	          if (operation === "join" && isCommitment(commitment)) groupOperation = { type: "join", commitment };
180	          else if (operation === "rotate" && isCommitment(oldCommitment) && isCommitment(newCommitment)) groupOperation = { type: "rotate", oldCommitment, newCommitment };
181	          else if (operation === "revoke" && isCommitment(commitment)) groupOperation = { type: "revoke", commitment };
182	          else {
183	            catalog.auditFailure("group_change_rejected", id, { operation: String(operation), reason: "invalid_group_operation" });
184	            return json(400, { error: "invalid_group_operation" });
185	          }
186	          const outcome = catalog.applyGroupOperation(id, groupOperation, expectedVersion as number);
187	          if (!outcome.ok) {
188	            if (outcome.reason === "poll_missing") return json(404, { error: "poll_not_found" });
189	            if (outcome.reason === "group_frozen" || outcome.reason === "group_version_changed" || outcome.reason === "poll_not_editable") return json(409, { error: outcome.reason });
190	            return json(400, { error: outcome.reason });
191	          }
192	          return json(201, { group: outcome.group });
193	        }
194	        if (segments[3] === "votes") {
195	          if (method !== "POST") return json(405, { error: "method_not_allowed" }, { Allow: "POST" });
196	          const poll = catalog.get(id);
197	          // Drafts are invisible to the public (404), matching detail/results.
198	          if (!poll || poll.status === "draft") return json(404, { error: "poll_not_found" });
199	          let body: unknown;
200	          try { body = JSON.parse(await readBody(request)); }
201	          catch { return json(400, { error: "invalid_json" }); }
202	          if (typeof body !== "object" || body === null) return json(400, { error: "invalid_vote" });
203	          const { optionId, proof, groupVersion } = body as { optionId?: unknown; proof?: unknown; groupVersion?: unknown };
204	          if (typeof optionId !== "string" || optionId.length === 0 || !isProofPayload(proof)) {
205	            return json(400, { error: "invalid_vote" });
206	          }
207	          if (groupVersion !== undefined && (!Number.isInteger(groupVersion) || (groupVersion as number) < 1)) {
208	            return json(400, { error: "invalid_vote" });
209	          }
210	          if (!poll.options.some(option => option.id === optionId)) return json(400, { error: "unknown_option" });
211	          // Only open polls before their deadline accept votes. Drafts and
212	          // closed/archived polls answer poll_closed; results stay public.
213	          if (poll.status !== "open" || Date.now() >= Date.parse(poll.closesAt)) return json(409, { error: "poll_closed" });
214	          // Resolve the immutable snapshot the proof must bind to: either the
215	          // explicitly requested version, or the version whose Merkle root the
216	          // proof carries (legacy clients that omit groupVersion). Historical
217	          // versions conflict; unknown roots are unprocessable.
218	          let snapshotVersion: number;
219	          if (groupVersion !== undefined) {
220	            if (groupVersion !== poll.groupVersion) return json(409, { error: "group_version_changed" });
221	            if (proof.merkleTreeRoot !== poll.merkleRoot) return json(422, { error: "proof_binding_mismatch" });
222	            snapshotVersion = groupVersion as number;
223	          } else {
224	            const snapshot = catalog.groupSnapshotByRoot(poll.id, proof.merkleTreeRoot);
225	            if (!snapshot) return json(422, { error: "unknown_merkle_root" });
226	            if (snapshot.version !== poll.groupVersion) return json(409, { error: "group_version_changed" });
227	            snapshotVersion = snapshot.version;
228	          }
229	          // The proof must also be bound to this poll (scope) and the chosen
230	          // option (message).
231	          let bound = false;
232	          try {
233	            bound = proof.scope === textToField(poll.id) && proof.message === textToField(optionId);
234	          } catch { bound = false; }
235	          if (!bound) return json(422, { error: "proof_binding_mismatch" });
236	          let valid = false;
237	          proverUsed = true;
238	          try { valid = await verifyProof(proof as unknown as SemaphoreProof); }
239	          catch { valid = false; }
240	          if (!valid) return json(422, { error: "invalid_proof" });
241	          // Snapshot confirmation, freeze-on-first-vote, nullifier dedup and
242	          // the vote write commit atomically; a concurrent group change makes
243	          // exactly one of the two succeed. A vote racing closesAt is rejected
244	          // as the poll is persisted closed in that same transaction.
245	          const outcome = catalog.commitVote(poll.id, optionId, proof.nullifier, snapshotVersion);
246	          if (!outcome.ok) {
247	            if (outcome.reason === "duplicate_nullifier") return json(409, { error: "duplicate_nullifier" });
248	            if (outcome.reason === "group_version_changed") return json(409, { error: "group_version_changed" });
249	            if (outcome.reason === "poll_closed") return json(409, { error: "poll_closed" });
250	            return json(400, { error: "unknown_option" });
251	          }
252	          return json(201, { receipt: outcome.receipt });
253	        }
254	      }
255	      if (segments[1] === "receipts" && segments.length === 3) {
256	        if (method !== "GET") return json(405, { error: "method_not_allowed" }, { Allow: "GET" });
257	        let id: string;
258	        try { id = decodeURIComponent(segments[2]); }
259	        catch { return json(400, { error: "invalid_receipt_id" }); }
260	        const receipt = catalog.receipt(id);
261	        return receipt ? json(200, { receipt }) : json(404, { error: "receipt_not_found" });
262	      }
263	      if (segments[1] === "receipts" && segments.length === 4 && segments[3] === "verify") {
264	        // A voter proves their ballot was counted by presenting the receipt's
265	        // own public fields; nothing here links the receipt to an identity.
266	        if (method !== "POST") return json(405, { error: "method_not_allowed" }, { Allow: "POST" });
267	        let id: string;
268	        try { id = decodeURIComponent(segments[2]); }
269	        catch { return json(400, { error: "invalid_receipt_id" }); }
270	        let body: unknown;
271	        try { body = JSON.parse(await readBody(request)); }
272	        catch { return json(400, { error: "invalid_json" }); }
273	        if (typeof body !== "object" || body === null) return json(400, { error: "invalid_verification" });
274	        const { pollId, optionId, nullifier } = body as Record<string, unknown>;
275	        if (typeof pollId !== "string" || typeof optionId !== "string" || typeof nullifier !== "string") {
276	          return json(400, { error: "invalid_verification" });
277	        }
278	        const receipt = catalog.receipt(id);
279	        if (!receipt) return json(404, { error: "receipt_not_found" });
280	        if (receipt.pollId !== pollId || receipt.optionId !== optionId || receipt.nullifier !== nullifier) {
281	          return json(422, { error: "receipt_mismatch" });
282	        }
283	        return json(200, { valid: true, receipt });
284	      }
285	      return json(404, { error: "not_found" });
286	    }
287	    if (request.method !== "GET") return json(405, { error: "method_not_allowed" }, { Allow: "GET" });
288	    let relativePath: string;
289	    try { relativePath = decodeURIComponent(url.pathname); }
290	    catch { return json(400, { error: "invalid_path" }); }
291	    const file = resolve(publicPath, relativePath === "/" ? "index.html" : `.${relativePath}`);
292	    if (!file.startsWith(`${resolve(publicPath)}${sep}`) || !existsSync(file) || !statSync(file).isFile()) return json(404, { error: "not_found" });
293	    response.writeHead(200, { "Content-Type": mime[extname(file)] ?? "application/octet-stream", "X-Content-Type-Options": "nosniff" });
294	    response.end(readFileSync(file));
295	  }
296	}
297	
298	function isStatus(value: unknown): value is PollStatus {
299	  return typeof value === "string" && (STATUSES as readonly string[]).includes(value);
300	}
301	
302	const DEFAULT_AUDIT_PAGE_SIZE = 50;
303	const MAX_AUDIT_PAGE_SIZE = 200;
304	
305	type ParseAuditQueryResult =
306	  | { ok: true; query: AuditQuery }
307	  | { ok: false; error: string };
308	
309	/**
310	 * Validates the audit trail filters. from/to must be strict timezone-aware
311	 * ISO 8601 instants (values only `Date.parse` tolerates loosely — date-only,
312	 * space-separated, zone-less, impossible calendar dates — are rejected) and
313	 * are inclusive at both ends; an inverted range is a 400. pageSize defaults
314	 * to 50 and is capped at 200.
315	 */
316	function parseAuditQuery(params: URLSearchParams): ParseAuditQueryResult {
317	  const query: AuditQuery = { page: 1, pageSize: DEFAULT_AUDIT_PAGE_SIZE };
318	  const from = params.get("from");
319	  const to = params.get("to");
320	  if (from !== null) {
321	    const parsed = parseInstant(from);
322	    if (!parsed) return { ok: false, error: "invalid_time_range" };
323	    query.from = parsed;
324	  }
325	  if (to !== null) {
326	    const parsed = parseInstant(to);
327	    if (!parsed) return { ok: false, error: "invalid_time_range" };
328	    query.to = parsed;
329	  }
330	  if (query.from !== undefined && query.to !== undefined && query.from > query.to) {
331	    return { ok: false, error: "invalid_time_range" };
332	  }
333	  const pollId = params.get("pollId");
334	  if (pollId !== null) query.pollId = pollId;
335	  const action = params.get("action");
336	  if (action !== null) query.action = action;
337	  const result = params.get("result");
338	  if (result !== null) query.result = result;
339	  const page = params.get("page");
340	  if (page !== null) {
341	    const parsed = Number(page);
342	    if (!Number.isInteger(parsed) || parsed < 1) return { ok: false, error: "invalid_pagination" };
343	    query.page = parsed;
344	  }
345	  const pageSize = params.get("pageSize");
346	  if (pageSize !== null) {
347	    const parsed = Number(pageSize);
348	    if (!Number.isInteger(parsed) || parsed < 1) return { ok: false, error: "invalid_pagination" };
349	    query.pageSize = Math.min(parsed, MAX_AUDIT_PAGE_SIZE);
350	  }
351	  return { ok: true, query };
352	}
353	
354	type ParsePollResult =
355	  | { ok: true; input: NewPollInput }
356	  | { ok: false; reason: string; pollId: string };
357	
358	/**
359	 * Validates a draft creation payload: all existing poll fields, a non-empty
360	 * list of distinct member commitments and at least two options with unique
361	 * ids. Returns a machine-readable error code on failure.
362	 */
363	function parseNewPoll(body: unknown): ParsePollResult {
364	  if (typeof body !== "object" || body === null) return { ok: false, reason: "invalid_poll", pollId: "unknown" };
365	  const b = body as Record<string, unknown>;
366	  const pollId = typeof b.id === "string" && b.id.trim() ? b.id : "unknown";
367	  const fail = (reason: string): ParsePollResult => ({ ok: false, reason, pollId });
368	  if (!isNonEmptyString(b.id, 128)) return fail("invalid_poll_id");
369	  if (!isNonEmptyString(b.title)) return fail("invalid_poll");
370	  if (!isNonEmptyString(b.summary)) return fail("invalid_poll");
371	  if (!isNonEmptyString(b.description, 20_000)) return fail("invalid_poll");
372	  if (!isNonEmptyString(b.organizer)) return fail("invalid_poll");
373	  const publishedAt = parseInstant(b.publishedAt);
374	  const closesAt = parseInstant(b.closesAt);
375	  if (!publishedAt || !closesAt) return fail("invalid_poll_dates");
376	  if (closesAt <= publishedAt) return fail("invalid_poll_dates");
377	  if (!Array.isArray(b.options) || b.options.length < 2) return fail("invalid_options");
378	  const optionIds = new Set<string>();
379	  const options: { id: string; label: string }[] = [];
380	  for (const option of b.options) {
381	    if (typeof option !== "object" || option === null) return fail("invalid_options");
382	    const { id, label } = option as { id?: unknown; label?: unknown };
383	    if (!isNonEmptyString(id, 128) || !isNonEmptyString(label)) return fail("invalid_options");
384	    if (optionIds.has(id)) return fail("duplicate_option_id");
385	    optionIds.add(id);
386	    options.push({ id, label });
387	  }
388	  if (!Array.isArray(b.commitments) || b.commitments.length === 0) return fail("invalid_commitments");
389	  const commitments: string[] = [];
390	  for (const commitment of b.commitments) {
391	    if (!isCommitment(commitment)) return fail("invalid_commitments");
392	    if (commitments.includes(commitment)) return fail("duplicate_commitment");
393	    commitments.push(commitment);
394	  }
395	  return {
396	    ok: true,
397	    input: {
398	      id: b.id, title: b.title, summary: b.summary, description: b.description, organizer: b.organizer,
399	      publishedAt, closesAt,
400	      options, commitments
401	    }
402	  };
403	}
404	
405	export type { AuditEvent };
406

