90	      id TEXT PRIMARY KEY, title TEXT NOT NULL, summary TEXT NOT NULL,
91	      description TEXT NOT NULL, organizer TEXT NOT NULL, status TEXT NOT NULL,
92	      published_at TEXT NOT NULL, closes_at TEXT NOT NULL, options_json TEXT NOT NULL
93	    );
94	    CREATE TABLE IF NOT EXISTS members (
95	      commitment TEXT PRIMARY KEY, position INTEGER NOT NULL UNIQUE
96	    );
97	    CREATE TABLE IF NOT EXISTS votes (
