122	    CREATE INDEX IF NOT EXISTS audit_events_time ON audit_events (at DESC, id DESC);
123	  `);
124	  // Migrate pre-versioning databases: add the group columns to existing polls.
125	  const pollColumns = new Set((db.prepare("PRAGMA table_info(polls)").all() as { name: string }[]).map(column => column.name));
