193	  }
194	  /**
195	   * Builds the immutable close snapshot: pollId, the group version at close,
196	   * the total and per-option counts (in the poll's option order) and the close
197	   * instant. The digest is the lowercase hex SHA-256 of the UTF-8 bytes of
198	   * JSON.stringify of those five fields, serialized in that exact order.
199	   */
200	  function buildSnapshot(pollId: string, closedAt: string): PollSnapshot {
201	    const row = pollRow(pollId);
202	    if (!row) throw new Error(`Cannot snapshot missing poll ${pollId}`);
203	    const counts = new Map(
204	      (db.prepare("SELECT option_id, count(*) AS count FROM votes WHERE poll_id = ? GROUP BY option_id").all(pollId) as { option_id: string; count: number }[])
205	        .map(entry => [entry.option_id, entry.count])
206	    );
207	    const options = (JSON.parse(row.options_json) as { id: string }[]).map(option => ({ id: option.id, count: counts.get(option.id) ?? 0 }));
208	    const fields = { pollId, groupVersion: row.group_version, total: options.reduce((sum, option) => sum + option.count, 0), options, closedAt };
209	    const digest = createHash("sha256").update(JSON.stringify(fields), "utf8").digest("hex");
210	    return { ...fields, digest };
211	  }
212	  /** Persist the close snapshot. Must be called inside the transaction that closes the poll. */
213	  function writeSnapshot(pollId: string, closedAt: string) {
214	    db.prepare("UPDATE polls SET snapshot_json = ? WHERE id = ?").run(JSON.stringify(buildSnapshot(pollId, closedAt)), pollId);
215	  }
216	  /** Persist an audit event for an authorized request whose change did not commit (validation/business failure). */
217	  function recordAudit(action: AuditAction, pollId: string, result: "failure", details: Record<string, unknown>, now = Date.now()) {
218	    insertAudit(action, pollId, result, details, new Date(now).toISOString());
219	  }
220	  function members(): string[] {
221	    return (db.prepare("SELECT commitment FROM members ORDER BY position").all() as { commitment: string }[]).map(row => row.commitment);
222	  }
223	  function pollRow(id: string): PollRow | undefined {
224	    return db.prepare("SELECT * FROM polls WHERE id = ?").get(id) as PollRow | undefined;
225	  }
226	  /**
227	   * Lazily persists the deadline transition for every open poll whose
228	   * closesAt has passed. Each status change and its audit row commit in one
229	   * transaction; a no-op read starts no write transaction. commitVote repeats
230	   * this check inside its own transaction, which is the authoritative
231	   * adjudication for a vote racing the cutoff.
232	   */
233	  function closeExpired(now = Date.now()) {
234	    const open = db.prepare("SELECT id, closes_at FROM polls WHERE status = 'open'").all() as { id: string; closes_at: string }[];
235	    const due = open.filter(row => now >= Date.parse(row.closes_at)).map(row => row.id);
236	    if (due.length === 0) return;
237	    db.exec("BEGIN IMMEDIATE");
238	    try {
239	      const at = new Date(now).toISOString();
240	      for (const pollId of due) {
241	        const result = db.prepare("UPDATE polls SET status = 'closed' WHERE id = ? AND status = 'open'").run(pollId);
242	        if (result.changes > 0) {
