244	          insertAudit("poll_status_change", pollId, "success", { from: "open", to: "closed", reason: "deadline" }, at);
245	        }
246	      }
247	      db.exec("COMMIT");
248	    } catch (error) { db.exec("ROLLBACK"); throw error; }
249	  }
250	  function currentSnapshot(pollId: string): GroupSnapshot | undefined {
251	    const row = db.prepare(`
252	      SELECT gv.* FROM polls p
253	      JOIN group_versions gv ON gv.poll_id = p.id AND gv.version = p.group_version
254	      WHERE p.id = ?
255	    `).get(pollId) as GroupVersionRow | undefined;
256	    return row ? toSnapshot(row) : undefined;
257	  }
258	  function summarize(row: PollRow): PollSummary {
259	    return {
260	      id: row.id, title: row.title, summary: row.summary, organizer: row.organizer,
261	      status: row.status, publishedAt: row.published_at, closesAt: row.closes_at,
262	      memberCount: currentSnapshot(row.id)?.commitments.length ?? 0, optionCount: JSON.parse(row.options_json).length
263	    };
264	  }
265	  return {
266	    /** Public catalog hides drafts; an authorized manager can list them too. */
267	    list(now = Date.now(), includeDrafts = false): PollSummary[] {
268	      closeExpired(now);
269	      const rows = db.prepare(includeDrafts ? "SELECT * FROM polls ORDER BY published_at DESC, id" : "SELECT * FROM polls WHERE status != 'draft' ORDER BY published_at DESC, id").all() as unknown as PollRow[];
