271	    },
272	    get(id: string, now = Date.now()): PollDetail | undefined {
273	      closeExpired(now);
274	      const row = pollRow(id);
275	      if (!row) return undefined;
276	      const snapshot = currentSnapshot(id);
277	      if (!snapshot) return undefined;
278	      return {
279	        ...summarize(row), description: row.description, options: JSON.parse(row.options_json),
280	        eligibleMemberCommitments: snapshot.commitments, groupVersion: snapshot.version, merkleRoot: snapshot.merkleRoot
281	      };
282	    },
283	    /**
284	     * Creates a poll in draft with its immutable version-1 member snapshot.
285	     * The insert, the snapshot and the success audit row commit together; a
286	     * conflicting id aborts everything (the caller audits that failure).
287	     */
288	    createPoll(input: NewPollInput, now = Date.now()): CreatePollOutcome {
289	      db.exec("BEGIN IMMEDIATE");
290	      try {
291	        if (pollRow(input.id)) { db.exec("ROLLBACK"); return { ok: false, reason: "poll_exists" }; }
