293	        db.prepare(`
294	          INSERT INTO polls (id, title, summary, description, organizer, status, published_at, closes_at, options_json, group_version, frozen_version)
295	          VALUES (?, ?, ?, ?, ?, 'draft', ?, ?, ?, 1, NULL)
296	        `).run(input.id, input.title, input.summary, input.description, input.organizer, input.publishedAt, input.closesAt, JSON.stringify(input.options));
297	        const merkleRoot = merkleRootOf(input.commitments);
