302	        const poll = this.get(input.id);
303	        if (!poll) throw new Error("Created poll could not be read back");
304	        return { ok: true, poll };
305	      } catch (error) {
306	        db.exec("ROLLBACK");
307	        throw error;
308	      }
309	    },
310	    /**
311	     * Applies a lifecycle transition draft→open→closed→archived with an
312	     * optimistic expectedStatus guard. The status update and its audit row
313	     * commit atomically; conflicts and illegal edges leave a failure event.
314	     */
315	    transitionStatus(pollId: string, target: PollStatus, expectedStatus: PollStatus, now = Date.now()): StatusTransitionOutcome {
316	      db.exec("BEGIN IMMEDIATE");
317	      // Every authorized attempt leaves an event; failures commit only the audit row.
318	      const reject = (reason: Exclude<StatusTransitionOutcome, { ok: true }>["reason"], actual?: PollStatus): StatusTransitionOutcome => {
319	        db.exec("ROLLBACK");
320	        recordAudit(
321	          "status_change_rejected", pollId, "failure",
322	          { requested: target, expected: expectedStatus, reason, ...(actual ? { actual } : {}) },
323	          now
324	        );
325	        return { ok: false, reason };
326	      };
327	      try {
328	        const row = pollRow(pollId);
329	        if (!row) return reject("poll_missing");
330	        if (!STATUSES.includes(target) || !STATUSES.includes(expectedStatus)) return reject("invalid_status", row.status);
331	        if (row.status !== expectedStatus) return reject("status_conflict", row.status);
332	        if (STATUS_FLOW[row.status] !== target) return reject("illegal_transition", row.status);
333	        const at = new Date(now).toISOString();
334	        db.prepare("UPDATE polls SET status = ? WHERE id = ?").run(target, pollId);
335	        // Closing captures the immutable tally snapshot in the same transaction.
336	        if (target === "closed") writeSnapshot(pollId, at);
337	        insertAudit("poll_status_change", pollId, "success", { from: row.status, to: target }, at);
338	        db.exec("COMMIT");
339	        return { ok: true, status: target };
340	      } catch (error) {
341	        db.exec("ROLLBACK");
342	        throw error;
343	      }
344	    },
345	    /** Record an authorized management request that failed before changing data (malformed payload, etc.). */
346	    auditFailure(action: AuditAction, pollId: string, details: Record<string, unknown>, now = Date.now()): void {
347	      recordAudit(action, pollId, "failure", details, now);
348	    },
349	    /** The immutable snapshot a poll currently points at, or a specific historical version. */
350	    groupSnapshot(pollId: string, version?: number): GroupSnapshot | undefined {
351	      if (version === undefined) return currentSnapshot(pollId);
352	      const row = db.prepare("SELECT * FROM group_versions WHERE poll_id = ? AND version = ?").get(pollId, version) as GroupVersionRow | undefined;
353	      return row ? toSnapshot(row) : undefined;
354	    },
355	    /** The snapshot whose Merkle root matches, used to place proofs from clients that omit groupVersion. */
356	    groupSnapshotByRoot(pollId: string, merkleRoot: string): GroupSnapshot | undefined {
357	      const row = db.prepare("SELECT * FROM group_versions WHERE poll_id = ? AND merkle_root = ? ORDER BY version DESC LIMIT 1").get(pollId, merkleRoot) as GroupVersionRow | undefined;
358	      return row ? toSnapshot(row) : undefined;
359	    },
360	    /**
361	     * Applies a membership change as a new immutable version. Membership may
362	     * only be edited while the poll is a draft, or while open with no votes
363	     * yet (the first vote freezes the version). The optimistic
364	     * expectedVersion check, the status/frozen checks and the pointer update
365	     * happen in one immediate transaction, so a concurrent vote either freezes
366	     * the group first (this then fails with group_frozen) or observes the new
367	     * version. Successful changes and rejected attempts are both audited.
368	     */
369	    applyGroupOperation(pollId: string, operation: GroupOperation, expectedVersion: number, now = Date.now()): GroupOperationOutcome {
370	      db.exec("BEGIN IMMEDIATE");
371	      // Business failures roll the (never-applied) change back but still leave
372	      // a failure audit event, committed on its own after the rollback.
373	      const reject = (reason: Exclude<GroupOperationOutcome, { ok: true }>["reason"], status?: PollStatus): GroupOperationOutcome => {
374	        db.exec("ROLLBACK");
375	        recordAudit(
376	          "group_change_rejected", pollId, "failure",
377	          { operation: operation.type, expectedVersion, reason, ...(status ? { status } : {}) },
378	          now
379	        );
380	        return { ok: false, reason };
381	      };
382	      try {
383	        const row = pollRow(pollId);
384	        if (!row) return reject("poll_missing");
385	        // An open poll past its deadline is semantically closed: persist the
386	        // deadline transition (with the rejected-edit event) and refuse it.
387	        if (row.status === "open" && now >= Date.parse(row.closes_at)) {
388	          const at = new Date(now).toISOString();
389	          db.prepare("UPDATE polls SET status = 'closed' WHERE id = ?").run(pollId);
390	          writeSnapshot(pollId, at);
391	          insertAudit("poll_status_change", pollId, "success", { from: "open", to: "closed", reason: "deadline" }, at);
392	          insertAudit("group_change_rejected", pollId, "failure", { operation: operation.type, expectedVersion, reason: "poll_not_editable", status: "closed", deadline: true }, at);
393	          db.exec("COMMIT");
394	          return { ok: false, reason: "poll_not_editable" };
395	        }
396	        const editable = row.status === "draft" || (row.status === "open" && row.frozen_version === null);
397	        if (!editable) return reject(row.status === "open" ? "group_frozen" : "poll_not_editable", row.status);
398	        if (row.group_version !== expectedVersion) return reject("group_version_changed", row.status);
399	        const snapshot = currentSnapshot(pollId);
400	        if (!snapshot) return reject("poll_missing");
401	        const commitments = [...snapshot.commitments];
402	        if (operation.type === "join") {
403	          if (commitments.includes(operation.commitment)) return reject("duplicate_commitment", row.status);
404	          commitments.push(operation.commitment);
405	        } else if (operation.type === "rotate") {
406	          const index = commitments.indexOf(operation.oldCommitment);
407	          if (index === -1) return reject("commitment_not_found", row.status);
408	          if (commitments.includes(operation.newCommitment)) return reject("duplicate_commitment", row.status);
409	          commitments[index] = operation.newCommitment;
410	        } else {
411	          const index = commitments.indexOf(operation.commitment);
412	          if (index === -1) return reject("commitment_not_found", row.status);
413	          if (commitments.length === 1) return reject("empty_group", row.status);
414	          commitments.splice(index, 1);
415	        }
416	        const version = expectedVersion + 1;
417	        const merkleRoot = merkleRootOf(commitments);
418	        const at = new Date(now).toISOString();
419	        db.prepare("INSERT INTO group_versions (poll_id, version, commitments_json, merkle_root, created_at) VALUES (?, ?, ?, ?, ?)")
420	          .run(pollId, version, JSON.stringify(commitments), merkleRoot, at);
421	        db.prepare("UPDATE polls SET group_version = ? WHERE id = ?").run(version, pollId);
422	        insertAudit("group_change", pollId, "success", { operation: operation.type, expectedVersion, version, memberCount: commitments.length }, at);
423	        db.exec("COMMIT");
424	        return { ok: true, group: { pollId, version, merkleRoot, memberCount: commitments.length, commitments } };
425	      } catch (error) {
426	        db.exec("ROLLBACK");
427	        throw error;
428	      }
429	    },
430	    /**
431	     * Re-validates the poll state, confirms the group version is still current,
432	     * freezes that version on the first accepted vote, rejects a reused
433	     * nullifier and persists the vote in a single immediate transaction; the
434	     * UNIQUE (poll_id, nullifier) index is the backstop against concurrent
435	     * duplicates and deduplicates across versions. When the deadline has
436	     * passed the poll is persisted as closed in that same transaction, so a
437	     * vote racing the cutoff is adjudicated by the transaction and rejected.
438	     */
439	    commitVote(pollId: string, optionId: string, nullifier: string, groupVersion: number, now = Date.now()): CommitVoteOutcome {
440	      db.exec("BEGIN IMMEDIATE");
441	      try {
442	        const row = pollRow(pollId);
443	        if (!row) { db.exec("ROLLBACK"); return { ok: false, reason: "poll_closed" }; }
444	        if (row.status !== "open") { db.exec("ROLLBACK"); return { ok: false, reason: "poll_closed" }; }
445	        if (now >= Date.parse(row.closes_at)) {
446	          // Atomic deadline transition: persist closed and refuse the out-of-window vote.
447	          const at = new Date(now).toISOString();
448	          db.prepare("UPDATE polls SET status = 'closed' WHERE id = ?").run(pollId);
449	          writeSnapshot(pollId, at);
450	          insertAudit("poll_status_change", pollId, "success", { from: "open", to: "closed", reason: "deadline" }, at);
451	          db.exec("COMMIT");
452	          return { ok: false, reason: "poll_closed" };
453	        }
454	        if (row.group_version !== groupVersion) { db.exec("ROLLBACK"); return { ok: false, reason: "group_version_changed" }; }
455	        const options = JSON.parse(row.options_json) as { id: string }[];
456	        if (!options.some(option => option.id === optionId)) { db.exec("ROLLBACK"); return { ok: false, reason: "invalid_option" }; }
457	        const duplicate = db.prepare("SELECT 1 AS found FROM votes WHERE poll_id = ? AND nullifier = ?").get(pollId, nullifier);
458	        if (duplicate) { db.exec("ROLLBACK"); return { ok: false, reason: "duplicate_nullifier" }; }
459	        const receipt: VoteReceipt = { id: randomUUID(), pollId, optionId, nullifier, acceptedAt: new Date(now).toISOString() };
460	        db.prepare("INSERT INTO votes (id, poll_id, option_id, nullifier, accepted_at) VALUES (?, ?, ?, ?, ?)")
461	          .run(receipt.id, receipt.pollId, receipt.optionId, receipt.nullifier, receipt.acceptedAt);
462	        if (row.frozen_version === null) db.prepare("UPDATE polls SET frozen_version = ? WHERE id = ?").run(groupVersion, pollId);
463	        db.exec("COMMIT");
464	        return { ok: true, receipt };
465	      } catch (error) {
466	        db.exec("ROLLBACK");
467	        if (error instanceof Error && error.message.includes("UNIQUE")) return { ok: false, reason: "duplicate_nullifier" };
468	        throw error;
469	      }
470	    },
471	    /** Results stay public for open/closed/archived polls; drafts have none. */
472	    results(pollId: string, now = Date.now()): PollResults | undefined {
473	      closeExpired(now);
474	      const row = pollRow(pollId);
475	      if (!row || row.status === "draft") return undefined;
476	      const counts = new Map(
477	        (db.prepare("SELECT option_id, count(*) AS count FROM votes WHERE poll_id = ? GROUP BY option_id").all(pollId) as { option_id: string; count: number }[])
478	          .map(entry => [entry.option_id, entry.count])
479	      );
480	      const options = (JSON.parse(row.options_json) as { id: string }[]).map(option => ({ id: option.id, count: counts.get(option.id) ?? 0 }));
481	      const result: PollResults = { pollId, total: options.reduce((sum, option) => sum + option.count, 0), options };
482	      // Closed and archived polls carry the immutable close snapshot; open has none.
483	      if ((row.status === "closed" || row.status === "archived") && row.snapshot_json) {
484	        result.snapshot = JSON.parse(row.snapshot_json) as PollSnapshot;
485	      }
486	      return result;
487	    },
488	    receipt(id: string): VoteReceipt | undefined {
489	      const row = db.prepare("SELECT * FROM votes WHERE id = ?").get(id) as VoteRow | undefined;
490	      return row ? toReceipt(row) : undefined;
491	    },
492	    /** Audit trail, newest first; persisted in SQLite so it survives restarts. */
493	    auditEvents(limit = 200): AuditEvent[] {
494	      const rows = db.prepare("SELECT * FROM audit_events ORDER BY at DESC, id DESC LIMIT ?").all(limit) as unknown as AuditRow[];
495	      return rows.map(toAuditEvent);
496	    },
497	    /**
498	     * Filtered, paginated audit trail, newest first. pollId/action/result
499	     * match exactly; from/to are inclusive ISO instants (stored timestamps are
500	     * canonical ISO strings, so lexicographic bounds are exact).
501	     */
502	    auditQuery(query: AuditQuery): AuditPage {
503	      const conditions: string[] = [];
504	      const params: string[] = [];
505	      if (query.pollId !== undefined) { conditions.push("poll_id = ?"); params.push(query.pollId); }
506	      if (query.action !== undefined) { conditions.push("action = ?"); params.push(query.action); }
507	      if (query.result !== undefined) { conditions.push("result = ?"); params.push(query.result); }
508	      if (query.from !== undefined) { conditions.push("at >= ?"); params.push(query.from); }
509	      if (query.to !== undefined) { conditions.push("at <= ?"); params.push(query.to); }
510	      const where = conditions.length > 0 ? `WHERE ${conditions.join(" AND ")}` : "";
511	      const total = (db.prepare(`SELECT count(*) AS count FROM audit_events ${where}`).get(...params) as { count: number }).count;
512	      const rows = db.prepare(`SELECT * FROM audit_events ${where} ORDER BY at DESC, id DESC LIMIT ? OFFSET ?`)
513	        .all(...params, query.pageSize, (query.page - 1) * query.pageSize) as unknown as AuditRow[];
514	      return {
515	        events: rows.map(toAuditEvent),
516	        total,
517	        page: query.page,
518	        pageSize: query.pageSize,
519	        totalPages: Math.ceil(total / query.pageSize)
520	      };
521	    },
522	    close() { db.close(); }
523	  };
524	}
