1	import test from "node:test";
2	import assert from "node:assert/strict";
3	import { mkdtempSync, rmSync } from "node:fs";
4	import { tmpdir } from "node:os";
5	import { join } from "node:path";
6	import { DatabaseSync } from "node:sqlite";
7	import type { Server } from "node:http";
8	import { Identity } from "@semaphore-protocol/identity";
9	import { Group } from "@semaphore-protocol/group";
10	import { generateProof } from "@semaphore-protocol/proof";
11	import { createApp } from "../src/app.ts";
12	import { terminateProverWorkers } from "../src/voting.ts";
13	import type { PollDetail, PollResults, SemaphoreProofPayload, VoteReceipt } from "../src/types.ts";
14	
15	// Release the snarkjs worker pool so the test process can exit.
16	test.after(() => terminateProverWorkers());
17	
18	async function serve(databasePath: string): Promise<{ server: Server; base: string }> {
19	  const server = createApp(databasePath);
20	  await new Promise<void>(done => server.listen(0, "127.0.0.1", done));
21	  const address = server.address();
22	  assert.ok(address && typeof address !== "string");
23	  return { server, base: `http://127.0.0.1:${address.port}` };
24	}
25	async function stop(server: Server) {
26	  server.closeAllConnections();
27	  await new Promise<void>((done, reject) => server.close(error => error ? reject(error) : done()));
28	}
29	async function pollDetail(base: string, id: string): Promise<PollDetail> {
30	  const response = await fetch(`${base}/api/polls/${encodeURIComponent(id)}`);
31	  assert.equal(response.status, 200);
32	  return ((await response.json()) as { poll: PollDetail }).poll;
33	}
34	async function proofFor(secret: string, optionId: string, poll: PollDetail): Promise<SemaphoreProofPayload> {
35	  const identity = new Identity(secret);
36	  const group = new Group(poll.eligibleMemberCommitments);
37	  return generateProof(identity, group, optionId, poll.id) as Promise<SemaphoreProofPayload>;
38	}
39	async function postVote(base: string, pollId: string, payload: unknown) {
40	  const response = await fetch(`${base}/api/polls/${encodeURIComponent(pollId)}/votes`, {
41	    method: "POST",
42	    headers: { "Content-Type": "application/json" },
43	    body: typeof payload === "string" ? payload : JSON.stringify(payload)
44	  });
45	  return { status: response.status, body: await response.json() as { receipt?: VoteReceipt; error?: string } };
46	}
47	
48	test("anonymous vote lifecycle: accept, deduplicate, reject tampering, tally", async () => {
49	  const { server, base } = await serve(":memory:");
50	  try {
51	    const poll = await pollDetail(base, "community-garden-autumn");
52	    const [optionA, optionB] = poll.options;
53	
54	    // Unknown poll and malformed submissions.
55	    const validProof = await proofFor("veilvote-demo-member-01", optionA.id, poll);
56	    assert.equal((await postVote(base, "missing-poll", { optionId: optionA.id, proof: validProof })).status, 404);
57	    assert.equal((await postVote(base, poll.id, "not json{")).status, 400);
58	    assert.equal((await postVote(base, poll.id, { optionId: optionA.id })).status, 400);
59	    assert.equal((await postVote(base, poll.id, { optionId: optionA.id, proof: { ...validProof, points: ["1"] } })).status, 400);
60	    assert.equal((await postVote(base, poll.id, { optionId: "no-such-option", proof: validProof })).status, 400);
61	    assert.equal((await fetch(`${base}/api/polls/${poll.id}/votes`)).status, 405);
62	
63	    // A valid vote is accepted with a receipt.
64	    const accepted = await postVote(base, poll.id, { optionId: optionA.id, proof: validProof });
65	    assert.equal(accepted.status, 201);
66	    const receipt = accepted.body.receipt!;
67	    assert.equal(receipt.pollId, poll.id);
68	    assert.equal(receipt.optionId, optionA.id);
69	    assert.equal(receipt.nullifier, validProof.nullifier);
70	    assert.ok(receipt.id && receipt.acceptedAt);
71	
72	    // The receipt is retrievable; unknown receipts are 404.
73	    const fetched = await fetch(`${base}/api/receipts/${receipt.id}`);
74	    assert.equal(fetched.status, 200);
75	    assert.deepEqual(((await fetched.json()) as { receipt: VoteReceipt }).receipt, receipt);
76	    assert.equal((await fetch(`${base}/api/receipts/nope`)).status, 404);
77	
78	    // The same nullifier cannot vote twice in this poll, even with a fresh proof.
79	    const replay = await postVote(base, poll.id, { optionId: optionB.id, proof: await proofFor("veilvote-demo-member-01", optionB.id, poll) });
80	    assert.equal(replay.status, 409);
81	    assert.equal(replay.body.error, "duplicate_nullifier");
82	
83	    // Tampering: proof bound to option A but submitted for option B.
84	    const swapped = await postVote(base, poll.id, { optionId: optionB.id, proof: await proofFor("veilvote-demo-member-02", optionA.id, poll) });
85	    assert.equal(swapped.status, 422);
86	    // Tampering: proof bound to another poll's scope.
87	    const otherPoll = await pollDetail(base, "shared-space-improvement");
88	    const wrongScope = await postVote(base, poll.id, { optionId: optionA.id, proof: await proofFor("veilvote-demo-member-03", optionA.id, otherPoll) });
89	    assert.equal(wrongScope.status, 422);
90	    // Tampering: corrupted nullifier breaks the cryptographic proof.
91	    const corrupted = await proofFor("veilvote-demo-member-04", optionA.id, poll);
92	    corrupted.nullifier = validProof.nullifier;
93	    assert.equal((await postVote(base, poll.id, { optionId: optionA.id, proof: corrupted })).status, 422);
94	
95	    // Results count the accepted vote and include zero-vote options.
96	    const result = ((await (await fetch(`${base}/api/polls/${poll.id}/results`)).json()) as { result: PollResults }).result;
97	    assert.equal(result.pollId, poll.id);
98	    assert.equal(result.total, 1);
99	    assert.deepEqual(result.options, poll.options.map(option => ({ id: option.id, count: option.id === optionA.id ? 1 : 0 })));
100	    assert.equal((await fetch(`${base}/api/polls/missing/results`)).status, 404);
101	  } finally {
102	    await stop(server);
103	  }
104	});
105	
106	test("votes and receipts survive a restart; closed polls reject votes", async () => {
107	  const directory = mkdtempSync(join(tmpdir(), "veilvote-votes-"));
108	  const path = join(directory, "veilvote.sqlite");
109	  try {
110	    const first = await serve(path);
111	    const poll = await pollDetail(first.base, "community-garden-autumn");
112	    const proof = await proofFor("veilvote-demo-member-05", poll.options[1].id, poll);
113	    const accepted = await postVote(first.base, poll.id, { optionId: poll.options[1].id, proof });
114	    assert.equal(accepted.status, 201);
115	    const receipt = accepted.body.receipt!;
116	    await stop(first.server);
117	
118	    const second = await serve(path);
119	    try {
120	      const result = ((await (await fetch(`${second.base}/api/polls/${poll.id}/results`)).json()) as { result: PollResults }).result;
121	      assert.equal(result.total, 1);
122	      assert.equal(result.options.find(option => option.id === poll.options[1].id)?.count, 1);
123	      const persisted = await fetch(`${second.base}/api/receipts/${receipt.id}`);
124	      assert.equal(persisted.status, 200);
125	      assert.deepEqual(((await persisted.json()) as { receipt: VoteReceipt }).receipt, receipt);
126	
127	      // Close the poll by moving its deadline into the past.
128	      const db = new DatabaseSync(path);
129	      db.prepare("UPDATE polls SET closes_at = ? WHERE id = ?").run(new Date(Date.now() - 1000).toISOString(), poll.id);
130	      db.close();
